async function main(ctx) {
  const input = ctx.input || {};
  const owner = String(input.owner || '').trim();
  const repo = String(input.repo || '').trim();
  const branch = String(input.branch || '').trim();
  const title = String(input.title || '').trim();
  const commitMessage = String(input.commitMessage || '').trim();
  if (!owner) throw new Error('owner is required');
  if (!repo) throw new Error('repo is required');
  if (!branch) throw new Error('branch is required');
  if (!title) throw new Error('title is required');
  if (!commitMessage) throw new Error('commitMessage is required');
  return {
    owner, repo, branch, title, commitMessage,
    base: String(input.base || 'main').trim(),
    body: input.body != null ? String(input.body) : '',
    draft: Boolean(input.draft)
  };
}

async function main(ctx) {
  const resp = ctx.lastOutputOf('create_pr') || {};
  const pr = (resp.body && typeof resp.body === 'object') ? resp.body : {};
  const push = ctx.lastOutputOf('git_push') || {};
  return {
    success: true,
    prNumber: pr.number ?? null,
    prUrl: pr.html_url || null,
    branch: (ctx.lastOutputOf('normalize_input') || {}).branch || null,
    pushExitCode: push.exitCode ?? null
  };
}
